import hashlib, binascii
def fp(data):
    h = hashlib.sha256(data).digest()
    return binascii.hexlify(h).decode()
LIST = {"leafnet": fp(b"leafnet v2")}
def verify(name, data):
    if name not in LIST:
        return "unknown"
    if fp(data) != LIST[name]:
        return "changed"
    return "ok"
print(verify("leafnet", b"leafnet v3"))

